using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests
{
 public sealed class SettingsSaveTests
 {
  static string Raw(StateData d,int version){var c=new UnitySaveCodec();string p=c.Encode(d),hash;using(var h=SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(p))).Replace("-","").ToLowerInvariant();return c.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=version,payload=p,sha256=hash});}
  [Test]public void Version15RetainsMotionPreferenceAndCreatesNoAudioOrLanguageHistory(){string dir=Path.Combine(Path.GetTempPath(),"unity-settings-v15-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Game.New(1000000);s.Workshop.reducedMotion=true;var d=StateData.From(s);d.settings=null;string raw=Raw(d,15),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,new UnitySaveCodec());var load=store.Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.Settings.effects,Is.False);Assert.That(load.State.Settings.musicEnabled,Is.False);Assert.That(load.State.Settings.hapticsEnabled,Is.False);var next=SettingsRules.Change(load.State,"language","pl");next=SettingsRules.Change(next,"music-volume",amount:.37);store.Save(next);var reload=new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt);Assert.That(reload.Writable,Is.True,reload.Message);Assert.That(reload.State.Settings.language,Is.EqualTo("pl"));Assert.That(reload.State.Settings.musicVolume,Is.EqualTo(.37));Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v15-original-*").Single()),Is.EqualTo(raw));}finally{Directory.Delete(dir,true);}}
  [Test]public void UnknownLanguageMissingSettingsAndInvalidVolumeLockOriginal(){string dir=Path.Combine(Path.GetTempPath(),"unity-settings-invalid-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");for(int i=0;i<3;i++){var d=StateData.From(Game.New(1000000));if(i==0)d.settings=null;if(i==1)d.settings.language="unknown";if(i==2)d.settings.musicVolume=1.1;string raw=Raw(d,16);File.WriteAllText(path,raw);Assert.That(new AtomicSaveStore(path,new UnitySaveCodec()).Load(1000000).Writable,Is.False);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));}}finally{Directory.Delete(dir,true);}}
 }
}
